def can_obtain_24(n):
    if n < 2:
        return 'NO'

    operations = []
    numbers = list(range(1, n + 1))

    while len(numbers) > 1:
        a = numbers.pop()
        b = numbers.pop()

        if a + b == 24:
            operations.append(f"{a} + {b} = {a + b}")
            numbers.append(a + b)
        elif a - b == 24:
            operations.append(f"{a} - {b} = {a - b}")
            numbers.append(a - b)
        elif a * b == 24:
            operations.append(f"{a} * {b} = {a * b}")
            numbers.append(a * b)
        else:
            numbers.append(a)
            numbers.append(b)

    if numbers[0] == 24:
        return 'YES\n' + '\n'.join(operations)
    else:
        return 'NO'

